with enriched as (select src.id, src.order_id, src.method, src.amount, src.paid_at, p.order_date, p.discount, p.status as order_status from payments src left join orders p on src.order_id = p.id), with_dims as (select s.id, s.order_id, s.amount, s.paid_at, p.channel, p.shipping_fee, p.status from enriched s left join orders p on s.order_id = p.id where p.status = 'RETURNED'), deduped as (select id, amount, paid_at, channel, shipping_fee, status from (select *, rank() over (partition by status order by paid_at desc) as row_num from with_dims) x where row_num = 1), gaps as (select *, case when lag(paid_at) over (partition by status order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by status order by paid_at, id) + interval '14' day then 1 else 0 end as is_new_burst from deduped), islands as (select *, sum(is_new_burst) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as burst_id from gaps) select id, amount, paid_at, channel, shipping_fee, status, is_new_burst, case when status rlike '^(COMPLETED|PENDING)$' then 'GROUP_B' when status rlike '^(CANCELLED|SHIPPED)$' then 'PRIORITY' else 'GROUP_A' end as status_zone from islands order by channel desc nulls first;
